const body = $input.item.json.body || $input.item.json;
const action = body.action; // 'create' | 'update' | 'delete'
const event  = body.event;

if (!event || !action) return [{ json: { skip: true } }];

const startMs = event.start_at ? new Date(event.start_at).getTime() : null;
const endMs   = event.end_at   ? new Date(event.end_at).getTime()   : null;

// Cor do tipo de evento (hex) — vem no metadata
const eventColor = event.metadata?.color || '#3b82f6';

// Mapeia hex para ID de cor do Google Calendar
const gcalColorMap = {
  '#3b82f6': '9',  // Blueberry — reuniao
  '#22c55e': '2',  // Sage — ligacao
  '#a855f7': '3',  // Grape — entrega
  '#f59e0b': '5',  // Banana — lembrete
  '#10b981': '2',  // Sage — captacao
  '#06b6d4': '7',  // Peacock — reuniao_integracao
  '#6366f1': '9',  // Blueberry — reuniao_planejamento
  '#8b5cf6': '3',  // Grape — reuniao_periodica
  '#f43f5e': '11', // Tomato — apresentacao_proposta
  '#6b7280': '8',  // Graphite — outro
};
const gcalColorId = gcalColorMap[eventColor] || '9';

// Converte UTC para horário local de Brasília (UTC-3) sem sufixo Z
// O Google Calendar usa o campo timeZone para interpretar — precisa receber o horário local
const toSaoPauloLocal = (utcStr) => {
  if (!utcStr) return null;
  const d = new Date(utcStr);
  // UTC-3 = subtrai 3h
  const local = new Date(d.getTime() - 3 * 60 * 60 * 1000);
  return local.toISOString().replace('Z', '').slice(0, 19);
};

return [{ json: {
  action,
  event_id: event.id,
  title: event.title,
  description: event.description || '',
  start_at: event.start_at,
  end_at: event.end_at,
  start_at_local: toSaoPauloLocal(event.start_at),
  end_at_local: toSaoPauloLocal(event.end_at),
  start_ms: startMs,
  end_ms: endMs,
  location: event.location || '',
  meeting_url: event.meeting_url || null,
  clickup_task_id: event.clickup_task_id,
  gcal_event_id: event.gcal_event_id || event.google_event_id,
  is_freelancer: event.is_freelancer || false,
  sync_clickup: event.is_freelancer === true,
  all_day: event.all_day || event.metadata?.all_day || false,
  clickup_list_id: event.metadata?.clickup_list_id || 'CLICKUP_AGENDA_LIST_ID',
  color: eventColor,
  gcal_color_id: gcalColorId
}}];

const clickupResult = $('ClickUp — Criar Evento').item.json;
const gcalResult    = $('Google Calendar — Criar Evento').item.json;
const prev = $('Parsear Evento').item.json;

return [{ json: {
  event_id: prev.event_id,
  clickup_task_id: clickupResult?.id || null,
  gcal_event_id: gcalResult?.id || null
}}];
